package org.firstinspires.ftc.teamcode;

import com.qualcomm.robotcore.eventloop.opmode.Autonomous;
import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;

@Autonomous(name = "SamplePinpointKids3 (Blocks to Java)")
public class SamplePinpointKids extends LinearOpMode {

  /**
   * Generated by Java→Blocks from Sample Pinpoint (Kids). Activate
   * a config whose device names match hardwareMap.get(...) strings.
   */
  @Override
  public void runOpMode() {
    // Init once — maps test_config devices and sets PIDF
    RobotMyBlocks.initRobot();
    RobotPinpointMyBlocks.initPinpoint();
    RobotPinpointMyBlocks.setPose(0, 0, 0);
    telemetry.addData("Status", "Ready — Sample Pinpoint (Kids)");
    telemetry.addData("Tip", "fwd 24 → turn 90 → strafe 12 → fwd 12 (pose PIDF)");
    telemetry.update();
    waitForStart();
    if (!opModeIsActive()) {
    }
    // Same sequence kids build from Pinpoint myBlocks
    RobotPinpointMyBlocks.driveForwardOdo(10, 0.5);
    RobotPinpointMyBlocks.strafeRightOdo(6, 0.4);
    RobotPinpointMyBlocks.driveForwardOdo(-10, 0.5);
    RobotPinpointMyBlocks.reportPose();
    RobotPinpointMyBlocks.stopDriveOdo();
    // Stop all drive motors
    RobotMyBlocks.stopDrive();
    telemetry.addData("Status", "Auto done");
    telemetry.update();
    sleep(500);
  }
}